export type ParsedStartDistributionInstruction<
  TProgram extends string = typeof FIDETOK_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    config: TAccountMetas[1];
    fideicomiso: TAccountMetas[2];
    mint: TAccountMetas[3];
    distribution: TAccountMetas[4];
    usdcMint: TAccountMetas[5];
    adminUsdcAccount: TAccountMetas[6];
    distributionVault: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    usdcTokenProgram: TAccountMetas[9];
    associatedTokenProgram: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
  };
  data: StartDistributionInstructionData;
};

export function parseStartDistributionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedStartDistributionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      config: getNextAccount(),
      fideicomiso: getNextAccount(),
      mint: getNextAccount(),
      distribution: getNextAccount(),
      usdcMint: getNextAccount(),
      adminUsdcAccount: getNextAccount(),
      distributionVault: getNextAccount(),
      tokenProgram: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getStartDistributionInstructionDataDecoder().decode(instruction.data),
  };
}
